const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cairns = ee.Geometry.Point(145.7781, -16.9186); // Cairns, QLD
  const cooktown = ee.Geometry.Point(145.248920, -15.475923); // Cooktown, QLD
  const startDate = '2025-01-31';
  const endDate = '2025-02-04';

  // 2. Data Acquisition & Check
  // Using GPM for daily precipitation data.
  const gpmCollection = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .select('precipitationCal');

  // Check if any images exist for the future date range.
  const collectionSize = gpmCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log('No rainfall data found for the future date range: 2025-01-31 to 2025-02-04.');
    console.log('Earth Engine contains historical and near-real-time data, not future forecasts.');
    console.log('A: C1');
    return;
  }

  // This part of the code will not be reached due to the future date,
  // but is included for logical completeness if the date were in the past.
  // 3. Processing
  const totalRainfall = gpmCollection.sum();

  // 4. Calculation
  const cairnsRainfall = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: cairns,
    scale: 10000, // GPM native resolution is ~10km
    maxPixels: 1e9
  }).get('precipitationCal');

  const cooktownRainfall = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: cooktown,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitationCal');

  const cairnsVal = cairnsRainfall.getInfo();
  const cooktownVal = cooktownRainfall.getInfo();

  // 5. Validation & Final Answer
  if (cairnsVal === null || cooktownVal === null) {
    console.log('Calculation failed: could not extract rainfall value for one or both locations.');
    console.log(`Cairns Value: ${cairnsVal}`);
    console.log(`Cooktown Value: ${cooktownVal}`);
    console.log('A: C3');
    return;
  }

  console.log(`Date Range: ${startDate} to ${endDate}`);
  console.log(`Total Images Found: ${collectionSize}`);
  console.log(`Total Rainfall in Cairns (mm): ${cairnsVal.toFixed(2)}`);
  console.log(`Total Rainfall in Cooktown (mm): ${cooktownVal.toFixed(2)}`);

  if (cairnsVal > cooktownVal) {
    console.log('A: A');
  } else {
    console.log('A: B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('A: D');
});
